import{_ as e,o as a,c as o,a2 as d}from"./chunks/framework.BC3NdntU.js";const q=JSON.parse('{"title":"B1 Vue vs React","description":"","frontmatter":{},"headers":[],"relativePath":"附录B-对比清单/B1-Vue与React对比.md","filePath":"附录B-对比清单/B1-Vue与React对比.md","lastUpdated":1788924729000}'),r={name:"附录B-对比清单/B1-Vue与React对比.md"};function l(i,t,u,s,c,n){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="b1-vue-vs-react" tabindex="-1">B1 Vue vs React <a class="header-anchor" href="#b1-vue-vs-react" aria-label="Permalink to &quot;B1 Vue vs React&quot;">​</a></h1><blockquote><p>附录 B · 对比清单</p></blockquote><hr><h2 id="总对比表" tabindex="-1">总对比表 <a class="header-anchor" href="#总对比表" aria-label="Permalink to &quot;总对比表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>Vue 3</th><th>React 18+</th></tr></thead><tbody><tr><td>响应式</td><td><code>Proxy</code> 依赖收集(自动)</td><td><code>setState</code> + 不可变数据(手动触发)</td></tr><tr><td>渲染</td><td>模板编译 + VNode + Diff(编译期优化)</td><td>JSX + Fiber(可中断调度)</td></tr><tr><td>数据流</td><td>双向绑定(<code>v-model</code>,框架内隐式)</td><td>单向数据流(回调上抛,显式)</td></tr><tr><td>更新粒度</td><td>组件级(依赖收集精准)</td><td>组件级(自上而下重渲,靠 memo 优化)</td></tr><tr><td>编译优化</td><td>静态提升/patchFlag/Block Tree/Vapor</td><td>React Compiler(自动 memo)</td></tr><tr><td>状态管理</td><td>Pinia</td><td>Redux / Zustand</td></tr><tr><td>SSR</td><td>Nuxt</td><td>Next.js</td></tr><tr><td>类型支持</td><td>好(TS 内置)</td><td>好</td></tr><tr><td>心智</td><td>模板 + 指令,上手快</td><td>JSX + Hooks,更&quot;函数式&quot;</td></tr><tr><td>生态</td><td>官方全家桶(路由/Pinia)</td><td>社区生态庞大</td></tr></tbody></table><hr><h2 id="各自优劣" tabindex="-1">各自优劣 <a class="header-anchor" href="#各自优劣" aria-label="Permalink to &quot;各自优劣&quot;">​</a></h2><p><strong>Vue:</strong></p><ul><li>✅ 上手快、模板直观、官方全家桶统一、响应式自动追踪(少写优化)</li><li>⚠️ 双向绑定在复杂状态流时隐式,<code>v-model</code> 语法糖多</li></ul><p><strong>React:</strong></p><ul><li>✅ 函数式/声明式纯粹、生态最庞大、可中断并发调度(大数据场景更强)、社区方案丰富</li><li>⚠️ 需要自己管理性能(memo/useMemo/useCallback)、Hooks 规则与闭包陷阱有门槛</li></ul><hr><h2 id="底层差异" tabindex="-1">底层差异 <a class="header-anchor" href="#底层差异" aria-label="Permalink to &quot;底层差异&quot;">​</a></h2><blockquote><p><strong>Vue 用「响应式 + 编译期优化」把 Diff 工作前移;React 用「不可变数据 + 运行时调度(Fiber)」把渲染做可中断。</strong> 殊途同归,都为了&quot;渲染不卡交互&quot;,只是路径不同。</p></blockquote><hr><h2 id="选型建议" tabindex="-1">选型建议 <a class="header-anchor" href="#选型建议" aria-label="Permalink to &quot;选型建议&quot;">​</a></h2><ul><li><strong>中小项目 / 团队偏模板 / 求上手快</strong> → Vue 3</li><li><strong>大型应用 / 团队函数式背景 / 求生态广度</strong> → React</li><li>两者都能胜任绝大多数场景,选<strong>团队更熟的那个</strong>最重要。</li></ul><hr><h2 id="深入思考" tabindex="-1">深入思考 <a class="header-anchor" href="#深入思考" aria-label="Permalink to &quot;深入思考&quot;">​</a></h2><ol><li><strong>设计哲学</strong>:Vue 偏&quot;渐进式 + 模板直观&quot;,React 偏&quot;函数式 + 最小 API 内核&quot;。这不是优劣,是取舍——Vue 把更多约定放进框架,React 把选择权交给生态。</li><li><strong>性能模型</strong>:Vue 依赖收集到&quot;属性级&quot;精准更新,React 默认&quot;组件级&quot;自上而下重渲。所以:响应式精准更新 Vue 更省心;&quot;先响应交互再渲染大数据&quot;的并发场景,React 的可中断调度更强。</li><li><strong>团队/招聘</strong>:React 生态更大、人才池更广;Vue 上手更快、团队内一致性更高。</li><li><strong>真正的决策点</strong>:两者都能做几乎所有事,选型应看&quot;团队现有能力 + 长期维护&quot;,而非追逐某一方的新特性。</li></ol><hr><p>📎 参考:Vue 官方文档、react.dev、卷六/卷七对应章节</p>',22)])])}const b=e(r,[["render",l]]);export{q as __pageData,b as default};
